create table sys_audit_log 
(
    id bigint generated by default as identity not null,
    organization_id integer,
    schema_name character varying(100) not null,
    table_name character varying(100) not null,
    record_id character varying(100),
    action character varying(10) not null,
    old_data jsonb,
    new_data jsonb,
    changed_user_id integer,
    request_id character varying(100),
    client_addr inet,
    application_name character varying(200),
    changed_date timestamp without time zone default now() not null,
    constraint chk_sys_audit_log_action CHECK (((action)::text = ANY ((ARRAY['INSERT'::character varying, 'UPDATE'::character varying, 'DELETE'::character varying])::text[]))),
    constraint sys_audit_log_pkey primary key (id)
);

create index idx_sys_audit_log_action on sys_audit_log using btree (action);
create index idx_sys_audit_log_changed_date on sys_audit_log using btree (changed_date);
create index idx_sys_audit_log_changed_user_id on sys_audit_log using btree (changed_user_id);
create index idx_sys_audit_log_organization_id on sys_audit_log using btree (organization_id);
create index idx_sys_audit_log_table_record on sys_audit_log using btree (table_name, record_id);

